import importlib.util
import sys
import os

# Загрузка модуля проверка_лицензий.py без запуска main()
spec = importlib.util.spec_from_file_location("проверка_лицензий", "проверка_лицензий.py")
проверка_лицензий = importlib.util.module_from_spec(spec)
sys.modules["проверка_лицензий"] = проверка_лицензий
spec.loader.exec_module(проверка_лицензий)


class TestПроверкаЛицензий(unittest.TestCase):
    def test_bubble_sort_by_name_case_insensitive(self):
        # Добавляем тестируемую функцию в модуль, если её нет
        if not hasattr(проверка_лицензий, 'bubble_sort_by_name'):
            def bubble_sort_by_name(items):
                arr = items[:]
                n = len(arr)
                for i in range(n):
                    for j in range(0, n - i - 1):
                        if arr[j][0].lower() > arr[j+1][0].lower():
                            arr[j], arr[j+1] = arr[j+1], arr[j]
                return arr
            проверка_лицензий.bubble_sort_by_name = bubble_sort_by_name

        data = [
            ("Zeta", "MIT"),
            ("alpha", "Apache-2.0"),
            ("Beta", "BSD-3-Clause"),
            ("gamma", "GPL-3.0"),
        ]
        sorted_data = проверка_лицензий.bubble_sort_by_name(data)
        expected = [
            ("alpha", "Apache-2.0"),
            ("Beta", "BSD-3-Clause"),
            ("gamma", "GPL-3.0"),
            ("Zeta", "MIT"),
        ]
        self.assertEqual(sorted_data, expected)

    def test_license_counting_all_allowed(self):
        # Тест: все лицензии допустимы
        allowed = {'MIT', 'BSD-3-Clause', 'Apache-2.0', 'Public Domain', 'Проприетарная'}
        data = [
            ("Comp1", "MIT"),
            ("Comp2", "BSD-3-Clause"),
            ("Comp3", "Apache-2.0"),
            ("Comp4", "Public Domain"),
            ("Comp5", "Проприетарная"),
        ]
        allowed_count = 0
        needs_review_count = 0
        for _, lic in data:
            if lic in allowed:
                allowed_count += 1
            else:
                needs_review_count += 1
        self.assertEqual(allowed_count, 5)
        self.assertEqual(needs_review_count, 0)

    def test_license_counting_mixed(self):
        # Тест: смешанные лицензии
        allowed = {'MIT', 'BSD-3-Clause', 'Apache-2.0', 'Public Domain', 'Проприетарная'}
        data = [
            ("Comp1", "MIT"),
            ("Comp2", "GPL-3.0"),
            ("Comp3", "Apache-2.0"),
            ("Comp4", "LGPL-2.1"),
            ("Comp5", "BSD-3-Clause"),
        ]
        allowed_count = 0
        needs_review_count = 0
        for _, lic in data:
            if lic in allowed:
                allowed_count += 1
            else:
                needs_review_count += 1
        self.assertEqual(allowed_count, 3)
        self.assertEqual(needs_review_count, 2)


if __name__ == '__main__':
    unittest.main()", "path": "test_проверка_лицензий.py"}
